func systemsForRemovedInstance(instanceName string, store sourcespawn.ConfigStore) []string {
	if store == nil {
		return nil
	}
	cfg := store.GetConfig().Get()
	if cfg == nil {
		return nil
	}
	cc, ok := cfg.Components[instanceName]
	if !ok {
		return nil
	}
	return systemsForComponentConfig(cc)
}

