func (a *statusAggregator) remove(instanceName string) bool {
	if _, ok := a.reports[instanceName]; !ok {
		return false
	}
	delete(a.reports, instanceName)
	if a.expectedCount > 0 {
		a.expectedCount--
	}
	return true
}

